with valid as (select id, store_id, product_id, sale_date, units, revenue - units as revenue_per_unit, revenue - units as revenue_per_unit_2 from store_sales where sale_date >= date '2023-08-19') select *, sum(revenue_per_unit) over w_recent as running_revenue_per_unit, lead(units, 2, 0) over w_recent_2 as next_units, round(units / sum(units) over (partition by product_id, store_id), 4) as units_share, sum(units) over (partition by store_id, product_id order by revenue_per_unit_2, id rows between unbounded preceding and current row) as running_units from valid where units >= 19 window w_recent as (partition by product_id, store_id order by revenue_per_unit_2, id rows between unbounded preceding and current row), w_recent_2 as (partition by store_id, product_id order by sale_date, id)
